// Mirrors resolveVariable, resolveFilterValue, conditionalFilters, the six filters,
// and the resolveVariableAndFilter reduce pipeline (including skip logic).

const resolveVariable = (path, data = {}) => {
  if (!path) {
    return undefined;
  }

  if (path === '$$') {
    return data;
  } else if (path[0] === '$') {
    path = path.substring(1);
  } else if (path === '&') {
    return data;
  }

  if (typeof data[path] !== 'undefined') {
    return data[path];
  }

  let parts = path.replace(/^{|}$/g, '').split('.');
  return parts.reduce((data, path) => {
    if ((data && typeof data === 'object' || Array.isArray(data)) && path in data) {
      return data[path];
    }
    return undefined;
  }, data);
};

const conditionalFilters = {
  isTrue: true,
  isFalse: true,
  isMatch: true,
  notMatch: true,
  isEquals: true,
  notEquals: true
