  isFalse: function(input, truthy, falsy) {
    return resolveFilterValue(input ? falsy : truthy, this);
  },
  isMatch: function(input, match, truthy, falsy) {
    match = resolveFilterValue(match, this);
    return match && new RegExp(match, 'i').test(String(input))
      ? resolveFilterValue(truthy, this)
      : resolveFilterValue(falsy, this);
  },
  notMatch: function(input, match, truthy, falsy) {
    match = resolveFilterValue(match, this);
    return match && !new RegExp(match, 'i').test(String(input))
      ? resolveFilterValue(truthy, this)
      : resolveFilterValue(falsy, this);
  },
  isEquals: function(input, value, truthy, falsy) {
