function computeOptions(msg, {multiple, loadOptions, inputValue, isOpen, options, selection, useNew}) {
  let filtedOptions =
    inputValue && isOpen && !loadOptions
      ? options.filter(o => (o.label || '').indexOf(inputValue) > -1)
      : options.concat();

  const selectionValues = selection.map(s => s.value);

  if (useNew && multiple && loadOptions) {
    filtedOptions = filtedOptions.filter(
      option => selectionValues.indexOf(option.value) < 0
    );
  }

  return filtedOptions.map(o => o.value);
}

const opts = [
  {label: 'A', value: 1},
  {label: 'B', value: 2},
  {label: 'C', value: 3}
];

const scenarios = [
  {name: 'multi+autoComplete filters selected from fetched list', multiple: true, loadOptions: true, inputValue: '', isOpen: true, options: opts, selection: [{value: 1}], expectNew: [2, 3], expectOld: [1, 2, 3]},
  {name: 'multi+autoComplete, no overlap -> unchanged', multiple: true, loadOptions: true, inputValue: '', isOpen: true, options: opts, selection: [{value: 9}], expectNew: [1, 2, 3], expectOld: [1, 2, 3]},
  {name: 'single+autoComplete -> no filtering', multiple: false, loadOptions: true, inputValue: '', isOpen: true, options: opts, selection: [{value: 1}], expectNew: [1, 2, 3], expectOld: [1, 2, 3]},
  {name: 'multi without autoComplete -> no filtering', multiple: true, loadOptions: false, inputValue: '', isOpen: true, options: opts, selection: [{value: 1}], expectNew: [1, 2, 3], expectOld: [1, 2, 3]},
  {name: 'multi+autoComplete all selected -> empty list', multiple: true, loadOptions: true, inputValue: '', isOpen: true, options: opts, selection: [{value: 1}, {value: 2}, {value: 3}], expectNew: [], expectOld: [1, 2, 3]},
  {name: 'multi+autoComplete with input search keeps filtering', multiple: true, loadOptions: false, inputValue: 'B', isOpen: true, options: opts, selection: [{value: 1}], expectNew: [2], expectOld: [2]}
];

let pass = 0;
for (const s of scenarios) {
  const oldR = computeOptions(s.name, s, false);
  const newR = computeOptions(s.name, s, true);
  const ok = JSON.stringify(newR) === JSON.stringify(s.expectNew) && JSON.stringify(oldR) === JSON.stringify(s.expectOld);
  ok && pass++;
  console.log(`${ok ? 'PASS' : 'FAIL'} ${s.name}`);
  if (!ok) {
    console.log('  old:', oldR, 'expectedOld:', s.expectOld);
    console.log('  new:', newR, 'expectedNew:', s.expectNew);
  }
}
console.log(`${pass}/${scenarios.length} passed`);
process.exit(pass === scenarios.length ? 0 : 1);

