cat > /tmp/opencode/skiprest_sim.js <<'EOF'
// Simulation replicating the skipRestOnCancel pattern applied across renderers.
// Pattern in ajax branches:
//   if (feedback && isVisible(feedback, data)) {
//     const confirmed = await openFeedback(feedback, data);
//     if (!confirmed && feedback.skipRestOnCancel) return;
//   }
//   <remaining action logic>

const isVisible = () => true; // assume visible for these cases

function makeResolver() {
  let resolveFn;
  const p = new Promise(res => (resolveFn = res));
  return {p, resolve: resolveFn};
}

function simulateAjaxBranch({feedback, confirmedValue, skipRestOnCancel, hasVision}) {
  const next = [];
  return (async () => {
    if (hasVision && isVisible(feedback, {})) {
      const confirmed = await new Promise(res => setTimeout(() => res(confirmedValue), 5));
      if (!confirmed && feedback.skipRestOnCancel) {
        return {skipped: true, next};
      }
    }
    next.push('redirect', 'reload', 'close'); // remaining action logic
    return {skipped: false, next};
  })();
}

async function run() {
  const results = {};

  // Case 1: no feedback -> remaining logic always runs (default preserved)
  results.noFeedback = await simulateAjaxBranch({hasVision: false, feedback: {}, confirmedValue: true, skipRestOnCancel: true});

  // Case 2: feedback visible, user confirms -> remaining logic runs
  results.confirmed = await simulateAjaxBranch({hasVision: true, feedback: {}, confirmedValue: true, skipRestOnCancel: true});

  // Case 3: feedback cancelled, option not set -> remaining logic runs (default preserved)
  results.cancelledNoOption = await simulateAjaxBranch({hasVision: true, feedback: {}, confirmedValue: false, skipRestOnCancel: false});

  // Case 4: feedback cancelled, option set -> remaining logic skipped
  results.cancelledWithOption = await simulateAjaxBranch({hasVision: true, feedback: {skipRestOnCancel: true}, confirmedValue: undefined, skipRestOnCancel: true});

  // Case 5: cancel via closeDialog() with undefined result -> still falsy -> skipped when option set
  results.cancelledUndefined = await simulateAjaxBranch({hasVision: true, feedback: {skipRestOnCancel: true}, confirmedValue: undefined, skipRestOnCancel: true});

  // Case 6: falsy-but-not-false dismiss value (0) -> treated as cancelled
  results.cancelledZero = await simulateAjaxBranch({hasVision: true, feedback: {skipRestOnCancel: true}, confirmedValue: 0, skipRestOnCancel: true});

  return results;
}

// ---- Form submit chain simulation (closure skipRest gating) ----
function simulateSubmitChain({feedbackVisible, confirmedValue, skipRestOnCancel, onSubmitReturnsFalse}) {
  let skipRest = false;
  const events = [];
  // submit(fn) -> store.submit resolves store.data regardless of fn result (modeled)
  const fn = values => {
    if (onSubmitReturnsFalse) return Promise.resolve(values);
    return Promise.resolve()
      .then(async response => {
        events.push('onSaved');
        if (feedbackVisible && isVisible(feedbackVisible, {})) {
          const confirmed = await new Promise(res => setTimeout(() => res(confirmedValue), 5));
          if (!confirmed && skipRestOnCancel) skipRest = true;
        }
        return values;
      });
  };
  return submit(fn).then(resolvedValues => {
    if (skipRest) { events.push('skipRest'); return resolvedValues; }
    events.push('onFinished');
    events.push('reset', 'redirectOrReload');
    return resolvedValues;
  });
}

async function submit(fn) {
  const values = {a: 1};
  await fn(values);
  return values; // store.submit resolves self.data
}

async function runSubmit() {
  const results = {};
  results.s_noFeedback = await simulateSubmitChain({feedbackVisible: null, confirmedValue: false, skipRestOnCancel: true, onSubmitReturnsFalse: false});
  results.s_confirmed = await simulateSubmitChain({feedbackVisible: {}, confirmedValue: true, skipRestOnCancel: true, onSubmitReturnsFalse: false});
  results.s_cancelledNoOption = await simulateSubmitChain({feedbackVisible: {}, confirmedValue: false, skipRestOnCancel: false, onSubmitReturnsFalse: false});
  results.s_cancelledWithOption = await simulateSubmitChain({feedbackVisible: {}, confirmedValue: false, skipRestOnCancel: true, onSubmitReturnsFalse: false});
  results.s_onSubmitFalse = await simulateSubmitChain({feedbackVisible: {}, confirmedValue: false, skipRestOnCancel: true, onSubmitReturnsFalse: true});
  return results;
}

(async () => {
  const r = await run();
  const s = await runSubmit();
  const assert = (name, cond) => console.log(`${cond ? 'PASS' : 'FAIL'} ${name}`);
  assert('case1 noFeedback -> rest runs', r.noFeedback.skipped === false && r.noFeedback.next.join(',') === 'redirect,reload,close');
  assert('case2 confirmed -> rest runs', r.confirmed.skipped === false && r.confirmed.next.join(',') === 'redirect,reload,close');
  assert('case3 cancelled, no option -> rest runs', r.cancelledNoOption.skipped === false);
  assert('case4 cancelled + option -> rest skipped', r.cancelledWithOption.skipped === true && r.cancelledWithOption.next.length === 0);
  assert('case5 cancel undefined + option -> rest skipped', r.cancelledUndefined.skipped === true);
  assert('case6 dismiss 0 + option -> rest skipped', r.cancelledZero.skipped === true);

  assert('submit: no feedback -> full rest runs', s.s_noFeedback.length === 4);
  assert('submit: confirmed -> full rest runs', s.s_confirmed.length === 4);
  assert('submit: cancelled, no option -> full rest runs', s.s_cancelledNoOption.length === 4);
  assert('submit: cancelled + option -> rest skipped (only onSaved + skipRest)', s.s_cancelledWithOption.join(',') === 'onSaved,skipRest');
  assert('submit: onSubmit false early return -> rest runs', s.s_onSubmitFalse.length === 4);

  console.log('\nAjax branch details:'); console.log(JSON.stringify(r, null, 1));
  console.log('Submit chain details:'); console.log(JSON.stringify(s, null, 1));
})();
