'use strict';

// =============================================================
// Faithful model of the FORM submit branch + Dialog.tryChildrenToHandle
// flow (src/renderers/Form/index.tsx, src/renderers/Dialog.tsx).
// We model the openFeedback resolution for three scenarios:
//   A) feedback dialog has an inner form   -> confirm resolves true
//   B) feedback dialog is body-only        -> confirm resolves false
//   C) user cancels the feedback dialog    -> resolves false
// =============================================================

class FormStore {
  constructor(data) {
    this.data = data || {};
    this.dialogOpen = false;
    this.dialogData = null;
    this.action = null;
    this.callbacks = new Map();
    this.pristine = {};
    this.reset = () => {};
  }
  setCurrentAction(a) { this.action = a; }
  openDialog(ctx, additional, cb) {
    this.dialogData = ctx;
    this.dialogOpen = true;
    if (cb) this.callbacks.set(ctx, cb);
  }
  closeDialog(result) {
    const cb = this.callbacks.get(this.dialogData);
    this.dialogOpen = false;
    if (cb) {
      this.callbacks.delete(this.dialogData);
      setTimeout(() => cb(result), 0);
    }
  }
  async saveRemote() { return {ok: true, data: {saved: 1}}; }
  submit(fn) {
    // mimics store.submit flow: yield fn(values) then return self.data
    return Promise.resolve(fn(this.data)).then(() => this.data);
  }
}

class Form {
  constructor(store) {
    this.store = store;
  }
  openFeedback(dialog, ctx) {
    return new Promise(resolve => {
      this.store.setCurrentAction({type: 'button', actionType: 'dialog', dialog});
      this.store.openDialog(ctx, undefined, confirmed => resolve(confirmed));
    });
  }
  handleDialogConfirm() {
    this.store.closeDialog(true);
  }
  handleDialogClose() {
    this.store.closeDialog(false);
  }
  // current code (submit branch)
  async handleAction(action, {onFinished, onSaved, resetAfterSubmit}) {
    const store = this.store;
    let skipRest = false;
    const values = await store.submit((valuesCb) => {
      // action has api -> effective
      return store
        .saveRemote(action.api || '/default', valuesCb, {})
        .then(async response => {
          onSaved && onSaved(valuesCb, response);
          if (action.feedback && action.feedback.visible !== false) {
            const confirmed = await this.openFeedback(action.feedback, store.data);
            if (!confirmed && action.feedback.skipRestOnCancel) {
              skipRest = true;
            }
          }
          return valuesCb;
        });
    });
    if (skipRest) {
      return {skipRest: true, values};
    }
    if (onFinished && onFinished(values, action) === false) {
      return {onFinishedFalse: true, values};
    }
    resetAfterSubmit && store.reset(onReset => {});
    return {skipRest: false, values};
  }
}

// Dialog.tryChildrenToHandle + handleAction (confirm), as in Dialog.tsx
function dialogHandleConfirm({form, valueResolve, onConfirm, log}) {
  // tryChildrenToHandle: finds the form, calls doAction, then onConfirm
  if (!form) {
    log('  [Dialog] no form target -> handleSelfClose');
    return Promise.resolve(false); // tryChildrenToHandle returned false -> handleSelfClose()
  }
  log('  [Dialog] tryChildrenToHandle -> form.doAction');
  return form
    .handleAction({type: 'button', actionType: 'submit', api: '/save', feedback: feedbackCfg, from: 'dialog'}, {})
    .then(ret => {
      log('  [Dialog] form.doAction resolved -> onConfirm?', JSON.stringify(ret));
      // in tryChildrenToHandle: if submit && close !== false -> onConfirm
      onConfirm && onConfirm();
      return ret;
    });
}

let feedbackCfg = null;

async function runScenario(name, {feedbackHasForm, feedbackCfg}) {
  console.log('\n==================== ' + name + ' ====================');
  global.feedbackCfg = feedbackCfg;
  const formStore = new FormStore();
  const form = new Form(formStore);

  const log = (...a) => {};
  let upperDialogClosed = false;
  const upperOnConfirm = () => { upperDialogClosed = true; log('  [UPPER] onConfirm -> closeDialog(true)'); };

  // user clicks UPPER dialog confirm button
  log('-- user clicks upper dialog confirm --');
  await dialogHandleConfirm({form, onConfirm: upperOnConfirm, log});

  // simulate feedback dialog rendering: user interaction
  const fb = feedbackCfg;
  if (fb.visible !== false) {
    log('-- feedback dialog opened, user clicks its CONFIRM --');
    if (feedbackHasForm) {
      form.handleDialogConfirm(); // closeDialog(true)
    } else {
      // tryChildrenToHandle: no form -> handleSelfClose -> onClose -> closeDialog(false)
      form.handleDialogClose();
    }
    // wait for closeDialog callback setTimeout
    await new Promise(r => setTimeout(r, 10));
    log('-- feedback resolved --');
  }
  await new Promise(r => setTimeout(r, 10));
  console.log((feedbackCfg.skipRestOnCancel ? '[skipRestOnCancel=true] ' : '[no skipRestOnCancel] ') + name + ' -> upper dialog closed: ' + upperDialogClosed);
  return upperDialogClosed;
}

(async () => {
  // Scenario matrix from the reported bug: confirm feedback, skipRestOnCancel true
  await runScenario('confirm feedback (feedback has inner form)', {
    feedbackHasForm: true,
    feedbackCfg: {skipRestOnCancel: true}
  });
  await runScenario('confirm feedback (body-only feedback)', {
    feedbackHasForm: false,
    feedbackCfg: {skipRestOnCancel: true}
  });
  await runScenario('cancel feedback (body-only feedback)', {
    feedbackHasForm: false,
    feedbackVisible: false,
    feedbackCfg: null
  });
})();

