'use strict';

// =============================================================
// Faithful model of current Form submit-branch + Dialog tryChildrenToHandle
// Flow for: dialog (with form body) confirm button that has feedback.
//
// Layers:
//   UPPER DIALOG (has a form body)  -- footer confirm button w/ feedback
//     handleAction -> confirm -> tryChildrenToHandle -> form.doAction(submit)
//     after doAction resolves -> onConfirm -> upper dialog closes
//   FORM (inside upper dialog) -- submit branch w/ skipRest flag (current code)
//   FEEDBACK dialog -- opened via form.openFeedback; confirm/cancel resolves promise
// =============================================================

function deferred() {
  let resolve, reject;
  const promise = new Promise((res, rej) => { resolve = res; reject = rej; });
  return {promise, resolve, reject};
}

class FakeStore {
  constructor() {
    this.data = {saved: 1};
    this.pristine = {};
    this.dialogOpen = false;
    this.dialogData = null;
    this.action = null;
    this._cb = null;
    this.finished = false;
  }
  setCurrentAction(a) { this.action = a; }
  openDialog(ctx, additional, cb) {
    this.dialogData = ctx; this.dialogOpen = true;
    if (cb) this._cb = cb;
  }
  closeDialog(result) {
    this.dialogOpen = false;
    if (this._cb) {
      const cb = this._cb; this._cb = null;
      setTimeout(() => cb(result), 5);
    }
  }
  reset() {}
  clearPersistData() {}
  async saveRemote() { return {ok: true, data: {}}; }
  submit(fn) {
    const chain = fn(this.data);
    return typeof chain === 'object' && chain && typeof chain.then === 'function'
      ? chain.then(() => this.data)
      : Promise.resolve(this.data);
  }
}

// ---- CURRENT code from src/renderers/Form/index.tsx (submit branch) ----
function formHandleAction(form, action, opts) {
  const {store, onFinished, resetAfterSubmit, redirect, reload} = opts;
  let skipRest = false;

  return Promise.resolve()
    .then(() => {
      return form.submit(store, (values) => {
        // isEffectiveApi true
        return store
          .saveRemote(action.api || '/default', values, {})
          .then(async response => {
            opts.onSaved && opts.onSaved(values, response);
            if (action.feedback && action.feedback.visible !== false) {
              const confirmed = await form.openFeedback(store, action.feedback);
              if (!confirmed && action.feedback.skipRestOnCancel) {
                skipRest = true;
              }
            }
            return values;
          });
      });
    })
    .then(values => {
      const out = {skipRest};
      if (skipRest) {
        return Object.assign(out, {earlyReturn: true, values});
      }
      if (onFinished && onFinished(values, action) === false) {
        return Object.assign(out, {values});
      }
      resetAfterSubmit && store.reset();
      return Object.assign(out, {values, ranReload: reload ? true : false});
    });
}

// ---- openFeedback ----
function openFeedback(store, dialog) {
  return new Promise(resolve => {
    store.setCurrentAction({type: 'button', actionType: 'dialog', dialog});
    store.openDialog({fb: true}, undefined, confirmed => resolve(confirmed));
  });
}

// ---- feedback dialog user interaction ----
// confirm-noform: footer 确认 of body-only feedback dialog:
//   handleAction confirm -> tryChildrenToHandle (no form) -> handleSelfClose -> onClose -> closeDialog(false)
// confirm-withform: feedback has inner form -> tryChildrenToHandle -> form submit -> onConfirm -> closeDialog(true)
// cancel: -> handleSelfClose -> onClose -> closeDialog(false)
function clickFeedbackConfirm(form, store, feedbackHasForm) {
  if (feedbackHasForm) {
    // tryChildrenToHandle found feedback form -> onConfirm -> Form.handleDialogConfirm -> closeDialog(true)
    form.handleDialogConfirm(store);
  } else {
    // no form -> handleSelfClose -> onClose -> Form.handleDialogClose -> closeDialog(false)
    form.handleDialogClose(store);
  }
}

// ---- upper dialog flow ----
// User clicks UPPER dialog footer confirm. Returns a promise for the tryChildrenToHandle .then,
// and flags whether upper onConfirm ran.
function upperDialogConfirmClick(form, opts) {
  const {store, onConfirm} = opts;
  const result = deferred();
  tryChildrenToHandle(form, store, {onConfirm, after: result.resolve});
  return result.promise;
}

function tryChildrenToHandle(form, store, {onConfirm, after}) {
  // finds the dialog body form, calls doAction
  const p = formHandleAction(form, {type: 'button', actionType: 'submit', api: '/save', feedback: globalFeedback}, {
    storeProps: () => store,
    store,
    onFinished: undefined,
    onSaved: () => {},
    resetAfterSubmit: true,
    redirect: undefined,
    reload: '/list'
  });
  p.then(ret => {
    // tryChildrenToHandle: (submit) && close!==false -> onConfirm
    if (onConfirm) onConfirm();
    after(ret);
  });
}

let globalFeedback = {skipRestOnCancel: true, visible: true};

async function run(name, feedbackHasForm) {
  console.log('\n==== ' + name + ' ====');
  const store = new FakeStore();
  const form = {
    submit: (s, fn) => s.submit(fn),
    openFeedback: (s, d) => openFeedback(s, d),
    handleDialogConfirm: (s) => s.closeDialog(true),
    handleDialogClose: (s) => s.closeDialog(false)
  };

  let upperClosed = false;
  const upperResp = upperDialogConfirmClick(form, {
    store, onConfirm: () => { upperClosed = true; }
  });

  // feedback dialog now open (dialogOpen true)
  await new Promise(r => setTimeout(r, 1)); // let form reach openFeedback

  // user interacts with feedback
  clickFeedbackConfirm(form, store, feedbackHasForm);

  const ret = await upperResp;
  await new Promise(r => setTimeout(r, 10));
  console.log(`  feedbackHasForm=${feedbackHasForm}  skipRest=${ret.skipRest}  earlyReturn=${!!ret.earlyReturn}  ranReload=${!!ret.ranReload}  UPPER_DIALOG_CLOSED=${upperClosed}`);
}

(async () => {
  globalFeedback = {skipRestOnCancel: true, visible: true};
  await run('CONFIRM feedback (feedback has inner form -> confirmed true)', true);
  await run('CONFIRM feedback (body-only feedback -> confirmed false)', false);
})();

