'use strict';

// =============================================================
// Verify the fix for: feedback dialog CONFIRM resolving falsy (=> wrongly skipping)
//
// Models the resolution semantics AFTER the fix:
//   - A body-only feedback dialog's default 确认 button now routes through the
//     dialog's `onConfirm` prop (-> parent.handleDialogConfirm -> closeDialog(true))
//     instead of handleSelfClose -> onClose -> closeDialog(false).
//   - All renderers' handleDialogConfirm/handleDialogClose pass true/false.
//   - FORM submit-branch skip logic is unchanged (only fires on falsy confirmed).
// =============================================================

function deferred() {
  let resolve, reject;
  const promise = new Promise((res) => (resolve = res));
  return {promise, resolve};
}

class FakeStore {
  constructor() { this.data = {saved: 1}; this.dialogOpen = false; this.action = null; this._cb = null; }
  setCurrentAction(a) { this.action = a; }
  openDialog(ctx, additional, cb) { this.dialogOpen = true; if (cb) this._cb = cb; }
  closeDialog(result) {
    this.dialogOpen = false;
    if (this._cb) { const cb = this._cb; this._cb = null; setTimeout(() => cb(result), 2); }
  }
  reset() {}
  async saveRemote() { return {ok: true, data: {}}; }
  submit(fn) {
    const r = fn(this.data);
    return r && typeof r.then === 'function' ? r.then(() => this.data) : Promise.resolve(this.data);
  }
}

// ---------- FORM (submit branch, current code) ----------
function formSubmitBranch(form, store, action, opts) {
  let skipRest = false;
  return Promise.resolve()
    .then(() => store.submit((values) =>
        store.saveRemote(action.api || '/default', values, {})
          .then(async () => {
            if (action.feedback && action.feedback.visible !== false) {
              const confirmed = await form.openFeedback(store, action.feedback);
              if (!confirmed && action.feedback.skipRestOnCancel) {
                skipRest = true;
              }
            }
            return values;
          })
      ))
    .then((values) => {
      if (skipRest) return {skipped: true, roll: 'skipRest', values, reloadRan: false};
      if (opts.onFinished && opts.onFinished(values, action) === false) return {skipped: true, roll: 'onFinished', values};
      opts.reset && store.reset();
      return {skipped: false, values, reloadRan: opts.reload ? true : false};
    });
}

function openFeedback(store) {
  return new Promise((resolve) => {
    store.setCurrentAction({type: 'button', actionType: 'dialog', dialog: {} });
    store.openDialog({fb: true}, undefined, (confirmed) => resolve(confirmed));
  });
}

// ---------- DIALOG renderer: user clicks footer confirm/cancel of the feedback dialog ----------
// AFTER the fix, confirm (even body-only) routes through onConfirm -> parent.handleDialogConfirm -> closeDialog(true)
function clickConfirm(form, store, feedbackHasForm) {
  if (feedbackHasForm) {
    // with-form: tryChildrenToHandle -> onConfirm -> parent.handleDialogConfirm -> closeDialog(true)
    form.handleDialogConfirm(store);
  } else {
    // body-only AFTER fix: fallback changed to call the onConfirm prop (parent handler)
    form.handleDialogConfirm(store); // parent's handleDialogConfirm -> closeDialog(true)
  }
}
function clickCancel(form, store) {
  // cancel -> handleSelfClose -> onClose -> parent.handleDialogClose -> closeDialog(false)
  form.handleDialogClose(store);
}

// ---------- upper dialog tryChildrenToHandle ----------
function upperDialogConfirm(form, store, opts) {
  const d = deferred();
  formSubmitBranch(form, store, {type: 'button', actionType: 'submit', api: '/save', feedback: globalFeedback}, {
    onFinished: undefined,
    reset: true,
    reload: '/list'
  }).then((ret) => {
    if (opts.onConfirm) opts.onConfirm();
    d.resolve(ret);
  });
  return d.promise;
}

let globalFeedback = {skipRestOnCancel: true, visible: true};

async function scenario(name, {feedbackHasForm, action, feedbackCfg, resolve} ) {
  console.log('\n==== ' + name + ' ====');
  globalFeedback = feedbackCfg;
  const store = new FakeStore();
  const form = {
    submit: (s, fn) => s.submit(fn),
    openFeedback: (s) => openFeedback(s),
    handleDialogConfirm: (s) => s.closeDialog(true),
    handleDialogClose: (s) => s.closeDialog(false)
  };

  let upperClosed = false;
  const upperResp = upperDialogConfirm(form, store, { onConfirm: () => { upperClosed = true; } });
  await new Promise((r) => setTimeout(r, 1));

  // user interacts with the feedback dialog
  if (action === 'confirm') clickConfirm(form, store, feedbackHasForm);
  else clickCancel(form, store);

  const ret = await upperResp;
  await new Promise((r) => setTimeout(r, 5));
  console.log(`  skipRest=${ret.skipped}  reloadRan=${ret.reloadRan}  UPPER_DIALOG_CLOSED=${upperClosed}  ${ret.skipped ? '[BUG: wrongly skipped on CONFIRM]' : '[OK]'}`);
  return {ok: !ret.skipped, closed: upperClosed};
}

(async () => {
  console.log('=== FORM context: feedback on dialog confirm button ===');
  await scenario('CONFIRM feedback, body-only feedback (reported bug) is NOT skipped', {
    feedbackHasForm: false, action: 'confirm', feedbackCfg: {skipRestOnCancel: true}
  });
  await scenario('CONFIRM feedback with inner form is NOT skipped', {
    feedbackHasForm: true, action: 'confirm', feedbackCfg: {skipRestOnCancel: true}
  });
  await scenario('CANCEL feedback body-only IS skipped', {
    feedbackHasForm: false, action: 'cancel', feedbackCfg: {skipRestOnCancel: true}
  });
  await scenario('CONFIRM feedback WITHOUT skipRestOnCancel keeps default behavior', {
    feedbackHasForm: false, action: 'confirm', feedbackCfg: {skipRestOnCancel: false}
  });
  await scenario('CANCEL feedback WITHOUT skipRestOnCancel keeps default behavior', {
    feedbackHasForm: false, action: 'cancel', feedbackCfg: {skipRestOnCancel: false}
  });
})();

