  new Promise((resolve) => {
    store.setCurrentAction({type: 'button', actionType: 'dialog', dialog: {}});
    store.openDialog({}, undefined, (confirmed) => resolve(confirmed));
  });

// DialogRenderer.handleAction ajax branch (current code)
function dialogAjaxBranch(store, action, closeSelf) {
  return store
    .saveRemote(action.api, store.data, {})
    .then(async () => {
      if (action.feedback && action.feedback.visible !== false) {
        const confirmed = await openFeedback(store);
        if (!confirmed && action.feedback.skipRestOnCancel) {
