        }
      }
      action.redirect && null;
      action.reload && null;
      if (action.close) closeSelf(); // action.close && this.handleSelfClose()
      return {skipped: false, closed: action.close ? true : false};
    })
    .catch(() => ({skipped: false, closed: false}));
}

async function scenario(name, confirmedVal, feedbackCfg, close) {
  const store = new Store();
