    `  confirmed=${String(confirmedVal)} skipRestCfg=${!!feedbackCfg.skipRestOnCancel} closed=${selfClosed} ` +
      `=> feedback confirm lead to ${ret.skipped ? 'SKIP (BUG for confirm)' : 'no-skip'}${selfClosed ? ', dialog CLOSED' : ', dialog stays open'}`
  );
  return {skipped: ret.skipped, closed: selfClosed};
}

(async () => {
